#!/usr/bin/env bash
set -euo pipefail

log=/home/eval/logs/access.log
report_dir=/home/eval/reports

mkdir -p "$report_dir"

awk '{ count[$4]++ } END {
  for (code in count) printf "%s %d\n", code, count[code]
}' "$log" | sort -n -k1,1 > "$report_dir/status.txt"

awk '$4 ~ /^5[0-9][0-9]$/ { print $2, $3 }' "$log" > "$report_dir/errors.txt"

stats=$(awk '{
  total++
  if ($4 ~ /^5[0-9][0-9]$/) errors++
} END {
  printf "%d %d\n", total, errors
}' "$log")

read -r total errors <<< "$stats"
printf 'total=%s errors=%s\n' "$total" "$errors"
exit 0
